local DRY_RUN = true local SS = game:GetService("ServerStorage") local existing = SS:FindFirstChild("Boombox") print("========================================") print("[Boombox] existing tool: " .. tostring(existing ~= nil)) print("[Boombox] DRY_RUN: " .. tostring(DRY_RUN)) print("========================================") if DRY_RUN then print("[Boombox] Would create ServerStorage.Boombox (Tool + Handle + RemoteEvent + 2 scripts).") print("[Boombox] Change DRY_RUN to false at the very start, then run again.") print("========================================") return end if existing then existing:Destroy() print("[Boombox] Replaced the old tool.") end local tool = Instance.new("Tool") tool.Name = "Boombox" tool.RequiresHandle = true tool.CanBeDropped = false tool.ToolTip = "Play any audio ID" local handle = Instance.new("Part") handle.Name = "Handle" handle.Size = Vector3.new(2, 1.2, 0.8) handle.BrickColor = BrickColor.new("Really black") handle.Material = Enum.Material.SmoothPlastic handle.TopSurface = Enum.SurfaceType.Smooth handle.BottomSurface = Enum.SurfaceType.Smooth handle.Parent = tool local sound = Instance.new("Sound") sound.Name = "BoomboxSound" sound.Volume = 1 sound.Looped = true sound.RollOffMaxDistance = 90 sound.Parent = handle local remote = Instance.new("RemoteEvent") remote.Name = "BoomboxRemote" remote.Parent = tool local sv = Instance.new("Script") sv.Name = "BoomboxServer" sv.Parent = tool local cl = Instance.new("LocalScript") cl.Name = "BoomboxClient" cl.Parent = tool tool.Parent = SS print("[Boombox] Created ServerStorage.Boombox") print("[Boombox] NOW PASTE THE TWO SCRIPT SOURCES:") print("[Boombox]   BoomboxServer  <- BoomboxServer.server.lua") print("[Boombox]   BoomboxClient  <- BoomboxTool.client.lua") print("========================================")
